-- GenDB engine variant Q15-commuted_comparisons: template q15.sql, kind commuted_comparisons (generated by generate.py; frozen)
WITH revenue0 AS (
  SELECT
    l_suppkey AS supplier_no,
    SUM(l_extendedprice * (
      1 - l_discount
    )) AS total_revenue
  FROM lineitem
  WHERE
    $1 <= l_shipdate AND $1 + INTERVAL '3 MONTH' > l_shipdate
  GROUP BY
    l_suppkey
)
SELECT
  s_suppkey,
  s_name,
  s_address,
  s_phone,
  total_revenue
FROM supplier, revenue0
WHERE
  supplier_no = s_suppkey
  AND (
    SELECT
      MAX(total_revenue)
    FROM revenue0
  ) = total_revenue
ORDER BY
  s_suppkey
